{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리의 병목을 파악한 내용을 인덱스 선택의 구체적인 근거로 연결할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 느렸던 상황",
          "task": "조회 쿼리에 적합한 인덱스를 판단하는 일",
          "action": "조회 조건과 실행 계획에서 확인한 내용을 인덱스 선택의 근거로 설명",
          "result": "관찰한 병목과 선택한 인덱스 사이의 연결"
        },
        "expectedEvidence": [
          "추가할 인덱스를 정하는 데 실제로 사용한 판단 근거",
          "그 근거와 관련된 조회 조건이나 실행 계획의 구체적인 내용",
          "확인한 내용이 선택한 인덱스 구성과 연결되는 이유"
        ]
      },
      "question": "포켓마켓의 운영 화면에서 신고 목록 조회가 느렸을 때, 조회 쿼리에 추가할 인덱스를 정한 근거는 무엇이었나요?",
      "answerTip": "당시 직접 확인한 내용을 중심으로 짧게 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 조회의 실제 조건이나 실행 계획에서 확인한 내용을 구체적으로 제시하고, 그것이 선택한 인덱스 구성의 근거가 된 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 조건에 맞춰 인덱스를 추가해야 한다는 일반적인 원칙은 말하지만, 신고 목록 조회에서 확인한 내용과의 연결은 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회에 인덱스를 추가한 근거를 제시하지 못하거나, 속도 개선 수치 등 다른 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송 오류의 원인을 좁히기 위해 실제 로그에서 어떤 기록을 우선 대조했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송된 상황",
          "task": "오류 추적의 출발점이 될 로그 기록을 정하는 일",
          "action": "가장 먼저 대조한 로그 기록과 비교한 항목을 구체적으로 설명",
          "result": "첫 로그 비교에서 확인하려 했던 차이 또는 일치 여부"
        },
        "expectedEvidence": [
          "가장 먼저 서로 비교한 구체적인 로그 기록",
          "비교 대상 기록을 구분한 항목이나 범위",
          "해당 기록에서 실제로 대조한 값이나 발생 순서"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 두 번 발송됐을 때, 로그에서 가장 먼저 서로 비교해 본 기록은 무엇이었나요?",
      "answerTip": "전체 경위를 길게 설명하기보다 질문받은 대목부터 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 로그에서 처음 대조한 기록을 특정하고, 발생 시각이나 실행 서버 등 실제로 비교한 항목을 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 발송 로그를 시간순으로 보거나 서버별로 비교한다는 일반적인 설명은 하지만, 처음 대조한 기록은 구체적으로 밝히지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송 로그에서 비교한 기록을 제시하지 못하거나, 잠금 적용 등 수정 조치만 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
